// =============================================================================
//  SECTION 4: ENTRY POINT
// =============================================================================

fn run_compliance_pipeline(fingerprint: u64) -> Result<u64> {
    COMPLIANCE_PIPELINE.iter().try_fold(fingerprint, |fingerprint, layer| layer(fingerprint))
}

fn parse_args(argv: &[String]) -> std::result::Result<Namespace, Exit> {
    let prog = argv.first().and_then(|arg0| Path::new(arg0).file_name()).map(|name| name.to_string_lossy());
    let mut parser = ArgumentParser::new(prog.as_deref().unwrap_or("hello-world"), "Prints hello world.");
    parser.add_argument(&["-v", "--verbose"], ActionKind::Count, "verbose logging to stderr (-vv for debug)");
    parser.add_argument(&["--disassemble"], ActionKind::StoreTrue, "dump the firmware listing to stderr");
    let version = ActionKind::Version(format!("hello-world {VERSION}"));
    parser.add_argument(&["--version"], version, "show program's version number and exit");
    parser.parse_args(argv.get(1..).unwrap_or_default())
}

fn greet(args: &Namespace) -> Result<()> {
    let kernel = Kernel::boot()?;
    if args.flag("disassemble") {
        let name = kernel.container.get::<EnterpriseConfiguration>("config")?.get("cpu", "firmware")?;
        let firmware = kernel.container.get::<FirmwareLoader>("firmware_loader")?.load(&name)?;
        eprintln!("{}", disassemble(&firmware.image).join("\n"));
    }
    let message = kernel.produce_greeting()?;
    let fingerprint = message_fingerprint(&message);
    if run_compliance_pipeline(fingerprint)? != fingerprint {
        return Err(compliance_violation(0, "pipeline aggregate"));
    }
    let (rounds, records) = (COMPLIANCE_PIPELINE.len(), REGULATORY_AUDIT_TRAIL.len());
    log_info!(LOG, "all {rounds} verification rounds passed; {records} audit records on file");
    kernel.render(&message)
}

fn main() -> ExitCode {
    let argv: Vec<String> = std::env::args_os().map(|arg| arg.to_string_lossy().into_owned()).collect();
    let args = match parse_args(&argv) {
        Ok(args) => args,
        Err(Exit(code)) => return ExitCode::from(code),
    };
    let levels = [logging::WARNING, logging::INFO, logging::DEBUG];
    logging::basic_config(levels[args.count("verbose").min(2) as usize]);

    match greet(&args) {
        Ok(()) => ExitCode::SUCCESS,
        Err(exc) if exc.is_security_violation() => {
            eprintln!("fatal: {exc}");
            ExitCode::from(3)
        }
        Err(exc) => {
            eprintln!("Traceback (most recent call last):\n  File \"src/main.rs\", in main");
            eprintln!("{}: {exc}", exc.kind.qualified_name());
            ExitCode::from(1)
        }
    }
}
